const s = $input.first().json;
const times = String(s.times || '').split(',').map(t => t.trim()).filter(Boolean);
const now = DateTime.now().setZone('Europe/Paris');
const out = [];
for (const t of times) {
  const parts = t.split(':').map(Number);
  const at = now.set({ hour: parts[0], minute: parts[1], second: 0, millisecond: 0 });
  if (at > now.plus({ minutes: 1 })) {
    out.push({ json: { time: t, scheduled_at: at.toISO(), version: Number(s.schedule_version) } });
  }
}
return out;

const s = $input.first().json;
let extra = [];
try { extra = JSON.parse(s.extra_questions || '[]'); } catch (e) { extra = []; }
const range = (a, b) => { const r = []; for (let i = a; i <= b; i++) r.push({ option: String(i) }); return r; };
const yesNo = { values: [{ option: 'Yes' }, { option: 'No' }] };
const fields = [
  { fieldLabel: 'Mood (1-10)', fieldType: 'dropdown', fieldOptions: { values: range(1, 10) }, requiredField: true },
  { fieldLabel: 'Did you sleep enough?', fieldType: 'radio', fieldOptions: yesNo, requiredField: true },
  { fieldLabel: 'Did you socialise?', fieldType: 'radio', fieldOptions: { values: [{ option: 'Yes, in person' }, { option: 'Kinda, online' }, { option: 'No' }] }, requiredField: true },
  { fieldLabel: 'Did you binge eat?', fieldType: 'radio', fieldOptions: yesNo, requiredField: true },
];
for (const q of extra) {
  if (q.type === 'scale') {
    fields.push({ fieldLabel: q.label, fieldType: 'dropdown', fieldOptions: { values: range(Number(q.min), Number(q.max)) }, requiredField: true });
  } else {
    fields.push({ fieldLabel: q.label, fieldType: 'radio', fieldOptions: yesNo, requiredField: true });
  }
}
return [{ json: { form_json: JSON.stringify(fields) } }];

const map = { 'Mood (1-10)': 'Mood', 'Did you sleep enough?': 'Slept Enough', 'Did you socialise?': 'Socialised', 'Did you binge eat?': 'Binge Ate' };
const now = DateTime.now().setZone('Europe/Paris');
return $input.all().map(item => {
  const d = item.json.data || {};
  const row = { Date: now.toFormat('yyyy-MM-dd'), Time: now.toFormat('HH:mm') };
  for (const [k, v] of Object.entries(d)) {
    if (k === 'respondedAt') continue;
    const col = map[k] || k;
    row[col] = /^\d+$/.test(String(v)) ? Number(v) : v;
  }
  return { json: row };
});

const msg = $('Telegram Commands').first().json.message || {};
const text = String(msg.text || '').trim();
const s = $input.first().json;
let extra = [];
try { extra = JSON.parse(s.extra_questions || '[]'); } catch (e) { extra = []; }
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const m = text.match(/^\/(\w+)(?:@\w+)?\s*([\s\S]*)$/);
const cmd = m ? m[1].toLowerCase() : '';
const arg = m ? m[2].trim() : '';
let action = 'reply';
let reply = '';
let times = s.times;
let version = Number(s.schedule_version) || 1;
const help = 'Commands:\n/times 10:00, 13:30, 17:00, 21:00 - set check-in times (any number)\n/addquestion Did you exercise? - add a yes/no question\n/addscale How motivated are you today? (1-5) - add a scale question\n/stats - stats for the last 3 days';

if (cmd === 'times') {
  const parsed = arg.split(/[,;\s]+/).filter(Boolean);
  const valid = [];
  const bad = [];
  for (const p of parsed) {
    const mm = p.match(/^([01]?\d|2[0-3])[:.h]([0-5]\d)$/);
    if (mm) valid.push(mm[1].padStart(2, '0') + ':' + mm[2]); else bad.push(p);
  }
  const uniq = Array.from(new Set(valid)).sort();
  if (!uniq.length || bad.length) {
    reply = 'I could not read those times' + (bad.length ? ' (' + esc(bad.join(', ')) + ')' : '') + '. Use 24h format, e.g. /times 09:00, 14:00, 20:30';
  } else {
    action = 'update_times';
    times = uniq.join(',');
    version = version + 1;
    reply = 'Done! You will now get ' + uniq.length + ' check-in' + (uniq.length > 1 ? 's' : '') + ' a day at: ' + uniq.join(', ') + '.';
  }
} else if (cmd === 'addquestion') {
  if (!arg) {
    reply = 'Please add the question text, e.g. /addquestion Did you exercise?';
  } else {
    extra.push({ label: arg, type: 'yesno' });
    action = 'update_questions';
    reply = 'Added yes/no question: <b>' + esc(arg) + '</b>. It will appear in your next check-in.';
  }
} else if (cmd === 'addscale') {
  const sm = arg.match(/^([\s\S]*?)\s*\(\s*(\d+)\s*-\s*(\d+)\s*\)\s*$/);
  let label = arg;
  let min = 1;
  let max = 10;
  if (sm) { label = sm[1].trim(); min = Number(sm[2]); max = Number(sm[3]); }
  if (!label) {
    reply = 'Please add the question text, e.g. /addscale How motivated are you today? (1-5)';
  } else if (min >= max || max - min > 20) {
    reply = 'The scale range looks off. Use something like (1-5) or (0-10).';
  } else {
    extra.push({ label: label, type: 'scale', min: min, max: max });
    action = 'update_questions';
    reply = 'Added scale question: <b>' + esc(label) + '</b> (' + min + '-' + max + '). It will appear in your next check-in.';
  }
} else if (cmd === 'stats') {
  action = 'stats';
} else {
  reply = help;
}

return [{ json: { action, reply, row_id: s.id, times, extra_questions: JSON.stringify(extra), schedule_version: version } }];

const SOC = 'Socialised';
const SOC_OPTS = [['Yes, in person', 'in person'], ['Kinda, online', 'online'], ['No', 'no']];
const normSoc = v => { const s = String(v ?? '').trim(); return s.toLowerCase() === 'yes' ? 'Yes, in person' : s; };
const socBreakdown = vals => SOC_OPTS.map(([o, short]) => short + ' ' + vals.filter(v => v === o).length).join(' · ');
const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0 && r.Date).map(r => (SOC in r && r[SOC] !== '' ? { ...r, [SOC]: normSoc(r[SOC]) } : r));
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
const median = a => { const s = [...a].sort((x, y) => x - y); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const fmt = n => Number.isInteger(n) ? String(n) : n.toFixed(1);
const today = DateTime.now().setZone('Europe/Paris').startOf('day');
const skip = new Set(['Date', 'Time', 'row_number']);
const lines = ['<b>Your last 3 days</b>'];
for (let back = 2; back >= 0; back--) {
  const day = today.minus({ days: back });
  const key = day.toFormat('yyyy-MM-dd');
  const dayRows = rows.filter(r => String(r.Date).slice(0, 10) === key);
  const title = day.toFormat('ccc d LLL') + (back === 0 ? ' (today)' : '');
  lines.push('');
  if (!dayRows.length) { lines.push('<b>' + title + '</b>: no check-ins'); continue; }
  lines.push('<b>' + title + '</b> - ' + dayRows.length + ' check-in' + (dayRows.length > 1 ? 's' : ''));
  const cols = [];
  for (const r of dayRows) for (const k of Object.keys(r)) if (!skip.has(k) && !cols.includes(k)) cols.push(k);
  if (cols.includes('Mood')) { cols.splice(cols.indexOf('Mood'), 1); cols.unshift('Mood'); }
  for (const c of cols) {
    const vals = dayRows.map(r => r[c]).filter(v => v !== '' && v !== null && v !== undefined);
    if (!vals.length) continue;
    if (c === SOC) { lines.push('- ' + esc(c) + ': ' + socBreakdown(vals)); continue; }
    const nums = vals.map(Number).filter(n => !isNaN(n));
    if (nums.length === vals.length) {
      lines.push('- ' + esc(c) + ': avg ' + avg(nums).toFixed(1) + ' (min ' + Math.min(...nums) + ', max ' + Math.max(...nums) + ')');
    } else {
      const yes = vals.filter(v => String(v).toLowerCase() === 'yes').length;
      lines.push('- ' + esc(c) + ': yes ' + yes + '/' + vals.length);
    }
  }
}
const from = today.minus({ days: 2 }).toFormat('yyyy-MM-dd');
const to = today.toFormat('yyyy-MM-dd');
const all = rows.filter(r => { const d = String(r.Date).slice(0, 10); return d >= from && d <= to; });
const moodOf = list => list.map(r => Number(r.Mood)).filter(n => !isNaN(n) && n > 0);
const moods = moodOf(all);
if (moods.length) {
  lines.push('');
  lines.push('<b>3-day mood average:</b> ' + avg(moods).toFixed(1) + ' over ' + moods.length + ' check-ins');
}
if (all.some(r => r[SOC])) {
  lines.push('');
  lines.push('<b>Mood by socialising (last 3 days)</b>');
  for (const [opt, short] of SOC_OPTS) {
    const m = moodOf(all.filter(r => r[SOC] === opt));
    const label = short.charAt(0).toUpperCase() + short.slice(1);
    lines.push('- ' + label + ': ' + (m.length ? 'mean ' + avg(m).toFixed(1) + ', median ' + fmt(median(m)) + ' (' + m.length + ' check-in' + (m.length > 1 ? 's' : '') + ')' : 'no check-ins'));
  }
}
return [{ json: { text: lines.join('\n') } }];

const SOC = 'Socialised';
const SOC_OPTS = [['Yes, in person', 'in person'], ['Kinda, online', 'online'], ['No', 'no']];
const normSoc = v => { const s = String(v ?? '').trim(); return s.toLowerCase() === 'yes' ? 'Yes, in person' : s; };
const socBreakdown = vals => SOC_OPTS.map(([o, short]) => short + ' ' + vals.filter(v => v === o).length).join(' · ');
const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0 && r.Date).map(r => (SOC in r && r[SOC] !== '' ? { ...r, [SOC]: normSoc(r[SOC]) } : r));
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const median = a => { const s = [...a].sort((x, y) => x - y); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const fmt = n => Number.isInteger(n) ? String(n) : n.toFixed(1);
const now = DateTime.now().setZone('Europe/Paris');
const monday = now.startOf('week');
const days = [];
for (let i = 0; i < 7; i++) days.push(monday.plus({ days: i }));
const keys = days.map(d => d.toFormat('yyyy-MM-dd'));
const week = rows.filter(r => keys.includes(String(r.Date).slice(0, 10)));
const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
const labels = days.map(d => d.toFormat('ccc d'));
const dailyMood = keys.map(k => {
  const m = week.filter(r => String(r.Date).slice(0, 10) === k).map(r => Number(r.Mood)).filter(n => !isNaN(n) && n > 0);
  const a = avg(m);
  return a === null ? null : Math.round(a * 10) / 10;
});
const skip = new Set(['Date', 'Time', 'row_number', 'Mood']);
const cols = [];
for (const r of week) for (const k of Object.keys(r)) if (!skip.has(k) && !cols.includes(k)) cols.push(k);
const yesLabels = [];
const yesPct = [];
const lines = [];
lines.push('<b>Your week: ' + monday.toFormat('d LLL') + ' - ' + now.toFormat('d LLL') + '</b>');
lines.push('');
if (!week.length) {
  lines.push('No check-ins were logged this week.');
} else {
  const moods = week.map(r => Number(r.Mood)).filter(n => !isNaN(n) && n > 0);
  lines.push('Check-ins answered: ' + week.length);
  if (moods.length) {
    lines.push('Average mood: <b>' + avg(moods).toFixed(1) + '</b> / 10 (lowest ' + Math.min(...moods) + ', highest ' + Math.max(...moods) + ')');
    const withData = keys.map((k, i) => ({ label: days[i].toFormat('cccc'), v: dailyMood[i] })).filter(x => x.v !== null);
    if (withData.length) {
      const best = withData.reduce((a, b) => (b.v > a.v ? b : a));
      const worst = withData.reduce((a, b) => (b.v < a.v ? b : a));
      lines.push('Best day: ' + best.label + ' (' + best.v + ') - toughest day: ' + worst.label + ' (' + worst.v + ')');
    }
    if (withData.length >= 2) {
      const half = Math.floor(withData.length / 2);
      const first = avg(withData.slice(0, half).map(x => x.v));
      const second = avg(withData.slice(withData.length - half).map(x => x.v));
      const diff = second - first;
      lines.push('Trend: ' + (Math.abs(diff) < 0.5 ? 'fairly stable' : diff > 0 ? 'improving towards the end of the week' : 'dipping towards the end of the week') + ' (' + (diff >= 0 ? '+' : '') + diff.toFixed(1) + ')');
    }
  }
  lines.push('');
  lines.push('<b>Daily average mood</b>');
  for (let i = 0; i < 7; i++) lines.push('- ' + labels[i] + ': ' + (dailyMood[i] === null ? 'no data' : dailyMood[i]));
  const other = [];
  for (const c of cols) {
    const vals = week.map(r => r[c]).filter(v => v !== '' && v !== null && v !== undefined);
    if (!vals.length) continue;
    if (c === SOC) {
      const inPerson = vals.filter(v => v === 'Yes, in person').length;
      other.push('- ' + esc(c) + ': ' + socBreakdown(vals));
      yesLabels.push('Socialised (in person)');
      yesPct.push(Math.round((inPerson / vals.length) * 100));
      continue;
    }
    const nums = vals.map(Number).filter(n => !isNaN(n));
    if (nums.length === vals.length) {
      other.push('- ' + esc(c) + ': avg ' + avg(nums).toFixed(1) + ' (min ' + Math.min(...nums) + ', max ' + Math.max(...nums) + ')');
    } else {
      const yes = vals.filter(v => String(v).toLowerCase() === 'yes').length;
      const pct = Math.round((yes / vals.length) * 100);
      other.push('- ' + esc(c) + ': yes ' + yes + '/' + vals.length + ' (' + pct + '%)');
      yesLabels.push(c);
      yesPct.push(pct);
    }
  }
  if (other.length) {
    lines.push('');
    lines.push('<b>Other answers</b>');
    for (const o of other) lines.push(o);
  }
}
return [{ json: { text: lines.join('\n'), has_data: week.length > 0, labels, daily_mood: dailyMood, yes_labels: yesLabels, yes_pct: yesPct } }];

const files = $input.all().map(i => i.json).filter(f => f && f.id);
if (!files.length) return [];
const pick = files[Math.floor(Math.random() * files.length)];
return [{ json: { id: pick.id, name: pick.name } }];
